from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import open, range
import os
from taf.ul.trs_e2e_fw.lib.call_utils.module.at import AT
from taf.ul.trs_e2e_fw.lib.call_utils.module.cli_utils import Cli_Utils
from taf.ul.trs_e2e_fw.lib.call_utils.module.exceptions import DeviceNotAttachedException, \
    IPAddressNotAssigned, DeviceNotDetectedException
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf import Iperf
from taf.ul.trs_e2e_fw.lib.call_utils.te_id import TeId
from taf.ul.trs_e2e_fw.lib.call_utils.ue import UE
from ute_common_store.store import Store
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from jinja2 import FileSystemLoader, Environment
import paramiko


logger = BackgroundLogger.Instance()
rule_table_num = 0


class Module(UE):
    """ This library provides keywords to control dongle. It currently supports
     Huawei dongle
    """

    def __init__(self, dut, apn, iperf_remote_ip, rat, device_config_name, ipv4_or_v6):
        # self.macaddress = macaddress
        self.ue_type = "module"
        self.rat = rat
        self.device_config_name = device_config_name
        self.ipv4_or_v6 = 'IP' if ipv4_or_v6 == 'ipv4' else 'IPV6'
        # product_id, device_id = dongle_id.split(':')
        self.te_id = TeId(dut, self.rat)
        ssh_session = self._ssh_to_device_host(rat, device_config_name)
        self.cli_utils_obj = Cli_Utils(ssh_session, iperf_remote_ip, self.ipv4_or_v6)
        self.at = AT(ssh_session, self.cli_utils_obj, rat, device_config_name, apn,
                     self.ipv4_or_v6)
        self.store = Store()
        global rule_table_num
        rule_table_num = rule_table_num + 1
        logger.debug(('rule_table_num', rule_table_num))
        self.rule_table_num = rule_table_num
        logger.debug(('self.rule_table_num', self.rule_table_num))
        self.tty_path = None
        self.ue_ip = None

    def attach(self, verify_teid=False, call_type='data'):
        """
        Function to attach the module
        """
        logger.debug('Attach Called')
        if call_type == 'data':
            self.cli_utils_obj.tty_path = self.at.tty_path = self.tty_path = \
                self.at.find_ttyUSBport_and_attach(self.rat, self.device_config_name, attach_sequence=call_type)
            self._prepare_quectel(['ue_devices', self.rat, self.device_config_name], self.tty_path)
            try:
                self.ue_ip = self.at.start_quectel_daemon_get_ueip()
                self.cli_utils_obj.add_route(self.ue_ip, self.rule_table_num)
                return self.ue_ip
            except (DeviceNotAttachedException, DeviceNotDetectedException, IPAddressNotAssigned) as err:
                logger.info('Error message: {}'.format(err))
                raise err
        else:
            # self.at.attach_for_voice()
            attempt = 1
            logger.info('###### Attach Command Sequence For Voice : {} '.format(attempt))
            while attempt <= 3:
                try:
                    self.cli_utils_obj.tty_path = self.at.tty_path = self.tty_path = \
                        self.at.find_ttyUSBport_and_attach(
                            self.rat, self.device_config_name, attach_sequence='voice')
                    return
                except DeviceNotDetectedException:
                    attempt += 1
                    self.cli_utils_obj.tty_path = self.tty_path = \
                        self.at.find_ttyUSBport_and_attach(self.rat, self.device_config_name,
                                                           attach_sequence='voice')
                except Exception:
                    attempt += 1
            raise DeviceNotAttachedException

    def detach(self):
        """
        Function to detach the module
        """

        max_attempts = 3
        self.cli_utils_obj.stop_quectel_command()
        for i in range(max_attempts):
            try:
                self.at.tty_path = self.at.find_ttyUSBport_and_detach(self.rat,
                                                                      self.device_config_name)
            except Exception as e:
                logger.debug("Failed while finding ttyUSBport to detach the device with exception: {0}. Retrying "
                             "attempt {1} of {2}..".format(str(e), i, max_attempts))
                continue
        if self.ue_ip:
            self.cli_utils_obj.delete_route(self.ue_ip, self.rule_table_num)

    def call_start(self, call_type='data', device_section=None, profile=None, **kwargs):
        """
        Function to start the call on the module
        """
        if call_type == 'data':
            iperf = Iperf(self.ue_ip, device_section, profile, 'module', self.rat,
                          self.device_config_name)
            self.store.add(iperf, alias=profile)
            iperf.start_data(profile)
        else:
            self.at.start_voice_call()

    def call_stop(self, call_type='data', profile=None):
        """
        Function to stop the call on module
        """
        if call_type.lower() == 'data':
            iperf = self.store.get(alias=profile)
            throughput_fields = iperf.stop_data(profile)
            self.store.remove(alias=profile)
            return throughput_fields
            # self.cli_utils_obj.delete_route(self.gw_ip)
        elif call_type.lower() == 'voice':
            self.at.stop_voice_call()
        else:
            logger.debug("Call type: {0} not supported".format(call_type))

    def configure_ue(self, **kwargs):
        """
        Function to configure UE
        """
        raise Exception('Configure UE operation not supported for Module yet')

    def call_teardown(self, **kwargs):
        """
        Function to act as a call teardown
        """
        pass

    def _ssh_to_device_host(self, rat, device_config_name):
        dongle_config_details = get_config_variable(["ue_devices", rat, device_config_name])
        remote_host = dongle_config_details.get('remote_ip', '127.0.0.1')
        remote_user = dongle_config_details.get('remote_user', 'ute')
        remote_pwd = dongle_config_details.get('remote_password', 'ute')
        tty_path = dongle_config_details.get('tty_path', '/dev/ttyUSB1')
        logger.debug("{0},{1},{2},{3}".format(remote_host, remote_user, remote_pwd, tty_path))
        ssh_session = paramiko.SSHClient()
        try:
            ssh_session.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh_session.connect(hostname=remote_host, username=remote_user, password=remote_pwd)
        except Exception as e:
            raise e
        return ssh_session

    def _prepare_quectel(self, device_config_path, tty_path):
        config_details = get_config_variable(device_config_path)
        config_details['tty_path'] = tty_path
        template_file = os.path.abspath(os.path.join(__file__, os.pardir, 'resources',
                                                     'quectel-chat-connect.template'))
        self._render_template(config_details, template_file)
        # template_file = os.path.abspath(os.path.join(__file__, os.pardir, 'resources',
        # 'quectel-ppp'))
        # self._render_template(config_details, template_file)

    def _render_template(self, config_details, template_file):
        loader = FileSystemLoader(os.path.dirname(template_file))
        env = Environment(loader=loader)
        template_file_name = os.path.basename(template_file)
        template = env.get_template(template_file_name)
        rendered_content = template.render(config_details, v4orv6=self.ipv4_or_v6)
        logger.debug('rendered_content: {}\n'.format(rendered_content))
        rendered_file = 'execution_logs/{}'.format(template_file_name)
        if not os.path.exists(os.path.dirname(rendered_file)):
            os.makedirs(os.path.dirname(rendered_file))
        with open(rendered_file, 'w') as f_file:
            f_file.write(rendered_content)
        target_file = '/home/pi/{}'.format(template_file_name)
        self.cli_utils_obj.upload_file_to_host(rendered_file, target_file)
        self.cli_utils_obj.execute_command('sudo cp {} /etc/ppp/peers/{}'.format(
            target_file, template_file_name))
